import pandas as pd

def earliest_trading_date_1995(trans):
    trans_1995 = trans[trans['date'].str.contains('1995')]
    earliest_date = trans_1995['date'].min()
    accounts = trans_1995[trans_1995['date'] == earliest_date]['account_id'].unique()
    return pd.DataFrame({'account_id': accounts})

import pandas as pd

def compute_feature(disp):
    result = disp[(disp['type'] == 'owner') | (disp['type'] == 'disponent')]
    result = result[(disp['account_id'] >= 1) & (disp['account_id'] <= 10)]
    return result.groupby('type').size()
